//! Protobuf types for the Ethereum foundational modules.
//!
//! Generated by the `buf.build/anthropics/buffa` plugin; run `substreams protogen` to regenerate.

macro_rules! include_buffa {
    ($package:literal) => {
        include!(concat!($package, ".mod.rs"));
    };
}

pub mod sf {
    pub mod substreams {
        include_buffa!("sf.substreams");

        pub mod ethereum {
            pub mod v1 {
                include_buffa!("sf.substreams.ethereum.v1");
            }
        }

        pub mod v1 {
            include_buffa!("sf.substreams.v1");
        }
    }
}
